import React from 'react';
import { useQuery } from '@tanstack/react-query';
import API from '../api/axiosClient';
import { FaHistory, FaArrowDown, FaArrowUp } from 'react-icons/fa';

export default function CompanyTransactions({ orgId }) {
    const { data: transactions, isLoading } = useQuery({
        queryKey: ['companyTransactions', orgId],
        queryFn: async () => {
            const res = await API.get(`/worker/${orgId}/transactions`);
            return res.data;
        },
        refetchInterval: 5000 // Poll every 5s for live terminal updates
    });

    if (isLoading) return <div className="text-gray-400 mt-6">Loading company logs...</div>;

    return (
        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl mt-8">
            <h3 className="text-xl font-semibold mb-4 flex items-center gap-2 text-indigo-400">
                <FaHistory /> Organization Transaction Ledger
            </h3>
            <div className="overflow-x-auto">
                <table className="w-full text-left text-sm text-gray-300">
                    <thead className="bg-gray-900 uppercase text-xs text-gray-400 border-b border-gray-700">
                        <tr>
                            <th className="p-3">Customer</th>
                            <th className="p-3">Email</th>
                            <th className="p-3">Type</th>
                            <th className="p-3">Amount</th>
                            <th className="p-3">Date</th>
                        </tr>
                    </thead>
                    <tbody>
                        {transactions?.map((tx) => (
                            <tr key={tx._id} className="border-b border-gray-700/50 hover:bg-gray-750">
                                <td className="p-3 font-medium text-white">{tx.userId?.name || 'Unknown User'}</td>
                                <td className="p-3 text-gray-400">{tx.userId?.email || 'N/A'}</td>
                                <td className="p-3">
                                    {tx.type === 'TOPUP' ? (
                                        <span className="text-emerald-400 flex items-center gap-1 font-semibold"><FaArrowUp /> Top-Up</span>
                                    ) : (
                                        <span className="text-indigo-400 flex items-center gap-1 font-semibold"><FaArrowDown /> Purchase</span>
                                    )}
                                </td>
                                <td className="p-3 font-mono font-bold">${tx.finalPaid.toFixed(2)}</td>
                                <td className="p-3 text-gray-400">{new Date(tx.createdAt).toLocaleString()}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
